"""为 S1 生成浏览器可直接阅读的中文方法专题。"""
from pathlib import Path
import csv
import json

from task2_localization import NOC_ZH

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / '交付文件' / '任务三_专题深挖' / 'S1_东道主效应'
TASK2 = ROOT / '交付文件' / '任务二_百年全景'

with (OUT/'host_summary.csv').open(encoding='utf-8-sig',newline='') as f:
    cases = list(csv.DictReader(f))
stats = json.loads((TASK2/'02_数据表'/'B_主场准实验摘要.json').read_text(encoding='utf-8'))
city = {1964:'东京',1988:'首尔',1992:'巴塞罗那',2000:'悉尼',2008:'北京',2012:'伦敦',2016:'里约热内卢',2020:'东京',2024:'巴黎'}
data = [{
    'year':int(x['Year']),'noc':x['NOC'],'name':NOC_ZH[x['NOC']],
    'city':city[int(x['Year'])],
    'before':round(float(x['pre_share']),2),
    'host':round(float(x['host_share']),2),
    'change':round(float(x['change_pp']),2),
    'gap':round(float(x['descriptive_gap_pp']),2),
    'after':round(float(x['post_share']),2) if x['post_share'] else None,
    'before_rows':int(x['pre_rows']),'host_rows':int(x['host_rows']),
} for x in cases]
payload = json.dumps(data,ensure_ascii=False,separators=(',',':'))
html = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>东道主效应｜任务三</title><style>
:root{--paper:#f5f1e8;--ink:#142d34;--teal:#247487;--gold:#c79039;--red:#ad4058;--line:#d4dad7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Microsoft YaHei",sans-serif}.s1-hero{padding:9vh 7vw 8vh;min-height:68vh}.s1-kicker{font-size:14px;color:var(--gold);font-weight:800;letter-spacing:.15em}.s1-hero h1{font-size:clamp(54px,8vw,112px);line-height:1.03;margin:22px 0}.s1-hero p{font-size:clamp(18px,2vw,23px);line-height:1.7;max-width:880px}.s1-main{max-width:1260px;margin:auto;padding:0 6vw 90px}.s1-section{padding:65px 0;border-top:1px solid var(--line)}.s1-section h2{font-size:clamp(32px,4vw,52px);margin:5px 0 18px}.s1-section p{line-height:1.85;max-width:900px}.s1-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.s1-facts article{border:1px solid var(--line);background:#ffffffb8;border-radius:18px;padding:25px}.s1-facts strong{display:block;font-size:clamp(32px,4vw,55px);color:var(--teal)}.s1-facts span{font-size:14px}.s1-picker{display:flex;gap:10px;flex-wrap:wrap;margin:25px 0}.s1-picker button{border:1px solid var(--line);background:#fff;border-radius:99px;padding:10px 15px;cursor:pointer}.s1-picker button[aria-pressed=true]{background:var(--ink);color:white}.s1-case{display:grid;grid-template-columns:1fr 1fr;gap:28px;padding:28px;background:#fff9;border:1px solid var(--line);border-radius:20px}.s1-case h3{font-size:32px;margin:0}.s1-case .s1-change{font-size:48px;color:var(--teal);font-weight:900}.s1-bars{display:grid;gap:16px;align-content:center}.s1-bar{display:grid;grid-template-columns:80px 1fr 72px;gap:10px;align-items:center}.s1-bar i{display:block;height:18px;border-radius:10px;background:var(--teal);min-width:3px}.s1-bar:nth-child(2) i{background:var(--red)}.s1-note{padding:25px;border-left:4px solid var(--gold);background:#f2e9d7;line-height:1.8}.s1-figure{width:100%;border-radius:16px;border:1px solid var(--line);margin:20px 0}.s1-links{display:flex;gap:12px;flex-wrap:wrap}.s1-links a{padding:12px 17px;border:1px solid var(--line);border-radius:10px;background:#fff;text-decoration:none}.s1-details{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.s1-details article{padding:24px;border:1px solid var(--line);border-radius:16px;background:#fff8}.s1-details h3{margin-top:0}@media(max-width:700px){.s1-facts,.s1-details,.s1-case{grid-template-columns:1fr}.s1-main{padding:0 20px 60px}.s1-section{padding:46px 0}.s1-hero{padding:110px 24px 50px}.s1-case .s1-change{font-size:36px}}
</style></head><body><header class="s1-hero"><div class="s1-kicker">任务三 / 专题 S1</div><h1>主场，真的会<br>改变奖牌吗？</h1><p>从九个现代主办案例出发，比较主办前后奖牌记录份额，再检验同期变化。选一个案例，亲自查看提升与反例。</p></header><main class="s1-main"><section class="s1-section"><span class="s1-kicker">先看结论</span><h2>主场提升常见，但并非必然</h2><div class="s1-facts"><article><strong>8 / 9</strong><span>主办届份额高于前届</span></article><article><strong>+__DID__</strong><span>九案例匹配双重差分均值，百分点</span></article><article><strong>__CI__</strong><span>案例自助法 95% 区间，百分点</span></article></div><p>这些指标使用运动员获奖记录份额。团队项目会产生多条记录，因此它们不能解释为官方小项奖牌份额。</p></section><section class="s1-section" id="案例"><span class="s1-kicker">逐案例探索</span><h2>选择东道主，查看变化</h2><div id="s1-picker" class="s1-picker" role="group" aria-label="选择主办案例"></div><div class="s1-case"><div><h3 id="s1-name"></h3><div class="s1-change" id="s1-change"></div><p id="s1-description"></p></div><div class="s1-bars" id="s1-bars"></div></div><p class="s1-note">“相对比较组变化”只表示与五个前届份额相近的代表团同期变化之差。匹配并不能消除所有混杂因素；巴西 2016 年自身份额下降，便是“主办必然增长”的反例。</p></section><section class="s1-section"><span class="s1-kicker">方法与边界</span><h2>证据一步一步增强</h2><div class="s1-details"><article><h3>前后比较</h3><p>先比较东道主上一届、主办届以及下一届的奖牌记录份额。2024 年尚无下一届观测。</p></article><article><h3>同期匹配</h3><p>按前届份额寻找五个非主办比较对象，避免根据主办届结果挑选对照。九案例匹配双重差分均值为 __DID__ 个百分点。</p></article><article><h3>不确定性检验</h3><p>案例自助法区间为 __CI__ 个百分点；在选定匹配集合内进行 50,000 次随机化安慰剂检验。这些检验反映给定设计下的稳定性。</p></article><article><h3>识别局限</h3><p>主办权并非随机；九个案例样本较小，政治、投入、参赛资格和项目结构可能共同变化。因此不将结果表述为无条件因果效应。</p></article></div><img class="s1-figure" src="../../任务二_百年全景/04_核心图表/B_主场效应准实验检验.png" alt="匹配双重差分、前趋势与安慰剂分布图"><p>更长时间窗的合成对照与稳健性结果见任务二图表和正式报告。</p><div class="s1-links"><a href="../../任务二_百年全景/04_核心图表/B_20届合成对照与稳健性.png">查看 20 届合成对照图 ↗</a><a href="../../任务二_百年全景/01_报告与说明/任务二_百年奥运全景_正式报告.pdf">阅读正式报告 ↗</a></div></section><section class="s1-section"><span class="s1-kicker">复现材料</span><h2>核对每个数字</h2><div class="s1-links"><a href="host_summary.csv">下载九案例摘要 ↓</a><a href="host_windows.csv">下载前后届窗口 ↓</a><a href="host_comparison_groups.csv">下载比较组名单 ↓</a><a href="../../任务二_百年全景/02_数据表/B_匹配DID逐案例.csv">下载匹配结果 ↓</a></div><p>主分析排除 1906 届；历史代表团按当届代码保留；奖牌按运动员记录行统计。方法和代码在交付文件的任务二复现脚本中。</p></section></main><script>const cases=__CASES__,picker=document.querySelector('#s1-picker');picker.innerHTML=cases.map((x,i)=>`<button type="button" data-index="${i}" aria-pressed="${i===0}">${x.year} ${x.name}</button>`).join('');function show(i){const x=cases[i],scale=Math.max(10,x.before,x.host,x.after||0);document.querySelector('#s1-name').textContent=`${x.year} · ${x.city} · ${x.name}`;document.querySelector('#s1-change').textContent=`${x.change>=0?'+':''}${x.change.toFixed(2)} 个百分点`;document.querySelector('#s1-description').textContent=`奖牌记录从 ${x.before_rows} 行变为 ${x.host_rows} 行。相对比较组同期变化差为 ${x.gap>=0?'+':''}${x.gap.toFixed(2)} 个百分点。${x.after===null?'下一届尚无观测。':`下一届份额为 ${x.after.toFixed(2)}%。`}`;document.querySelector('#s1-bars').innerHTML=[['主办前',x.before],['主办届',x.host],...(x.after===null?[]:[['主办后',x.after]])].map(([label,value])=>`<div class="s1-bar"><span>${label}</span><div><i style="width:${value/scale*100}%"></i></div><b>${value.toFixed(2)}%</b></div>`).join('');picker.querySelectorAll('button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)))}picker.onclick=e=>{let b=e.target.closest('button[data-index]');if(b)show(+b.dataset.index)};show(0);</script></body></html>'''
html = html.replace('__CASES__',payload).replace('__DID__',f"{stats['matched_did_mean_pp']:.2f}").replace('__CI__',f"[{stats['bootstrap_ci95'][0]:.2f}, {stats['bootstrap_ci95'][1]:.2f}]")
(OUT/'index.html').write_text(html,encoding='utf-8')
print(OUT/'index.html')
